import type { Readable } from "node:stream";

/** An object read back from storage. */
export interface StoredObject {
  body: ReadableStream<Uint8Array>;
  /** Byte length when the backend reports it. */
  size?: number;
}

/**
 * Where attachment bytes live. Keys are generated by the server from ids only
 * (`<workspaceId>/<uuid>`), never from filenames or other client input; implementations still
 * refuse anything else (`assertStorageKey`).
 */
export interface Storage {
  readonly kind: "local" | "s3" | "memory";
  /**
   * Stores `body` under `key`, replacing nothing (keys are fresh). The caller enforces the size
   * limit while streaming, so implementations may buffer up to that limit. When `body` errors the
   * object must not be left behind.
   */
  put(key: string, body: Readable | AsyncIterable<Uint8Array>, info: { contentType: string }): Promise<void>;
  /** The object, or null when it does not exist. */
  get(key: string): Promise<StoredObject | null>;
  /** Removes the object; a missing object is not an error. */
  delete(key: string): Promise<void>;
}

const KEY =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

/** Defence in depth against path traversal: only `<uuid>/<uuid>` keys are accepted. */
export function assertStorageKey(key: string) {
  if (!KEY.test(key)) throw new Error(`Invalid storage key: ${JSON.stringify(key)}`);
}
